/* @lc app=leetcode id=2040 lang=kotlin */ class Solution { fun ub(a: IntArray, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] <= v) m + 1 to hi else lo to m } }.last().first fun cnt(n1: IntArray, n2: IntArray, x: Long): Long = n1.sumOf { a -> if (a > 0) ub(n2, Math.floorDiv(x, a.toLong())).toLong() else if (a < 0) (n2.size - ub(n2, -Math.floorDiv(x, -a.toLong()) - 1)).toLong() else if (x >= 0) n2.size.toLong() else 0L } fun kthSmallestProduct(nums1: IntArray, nums2: IntArray, k: Long): Long = generateSequence(-10_000_000_000L to 10_000_000_000L) { (lo, hi) -> if (lo >= hi) null else Math.floorDiv(lo + hi, 2L).let { mid -> if (cnt(nums1, nums2, mid) >= k) lo to mid else mid + 1 to hi } }.last().first }